def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        bid = min(budget, 8.0)
        return float(max(0.0, bid))

    prev_bids = []
    rich_aggressive = 0
    desperate_count = 0
    for opp in alive:
        prev = opp.get('previous_trace', {}) or {}
        pbid = prev.get('bid')
        if pbid is not None:
            prev_bids.append(float(pbid))
        if opp.get('budget', 0) >= 300:
            rich_aggressive += 1
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            desperate_count += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    units = supply / float(WATER_REQ)

    if hp <= 2 or no_water >= 2:
        bid = min(budget, max(65.0, highest_prev * 0.75 + 5.0))
        return float(max(0.0, bid))

    if hp <= 4 or no_water >= 1:
        bid = min(budget, max(42.0, min(78.0, avg_prev * 0.45 + 8.0)))
        return float(max(0.0, bid))

    if units >= 1.9:
        bid = 9.0
    elif units >= 1.45:
        bid = 14.0
    else:
        bid = 22.0

    if highest_prev >= 120:
        bid -= 4.0
    elif highest_prev >= 80:
        bid -= 2.0
    elif highest_prev <= 20 and len(prev_bids) > 0:
        bid += 3.0

    if desperate_count >= 2:
        bid += 6.0
    elif desperate_count == 1:
        bid += 3.0

    if rich_aggressive >= 2 and hp >= 6:
        bid -= 3.0

    if day >= 8 and hp >= 6:
        bid -= 2.0

    bid = max(5.0, bid)
    bid = min(budget, bid)
    return float(max(0.0, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], 20.0)

    yesterday_bids = [opp['previous_trace']['bid'] for opp in alive_opponents if opp.get('previous_trace') and opp['previous_trace'].get('bid') is not None]

    max_prev = max(yesterday_bids) if yesterday_bids else 0

    if my_status['hp'] <= 3:
        return min(my_status['budget'], max_prev * 1.1 + 10.0)

