        return min(my_status['budget'], max_prev * 1.05)

    target = max(40.0, max_prev * 0.95)
    return min(my_status['budget'], target)

def get_bid(day_context, my_status, opponents_status):
    MY_WATER_REQUIREMENT = 8
    MY_DAILY_SALARY = 140

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # Calculate total water demand from all alive agents (including myself)
    total_water_demand = MY_WATER_REQUIREMENT
    for opp in alive_opponents:
        total_water_demand += opp['water_requirement']

    # Determine if water is scarce: supply is less than total water needed
    is_water_scarce = day_context['supply'] < total_water_demand

    # If no alive opponents, bid a conservative amount
    if not alive_opponents:
        return min(my_status['budget'], MY_DAILY_SALARY * 0.4)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    calculated_bid = MY_DAILY_SALARY * 0.55 # Default moderate bid

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        # High pressure threshold: 85% of daily salary
        if highest_prev_bid >= MY_DAILY_SALARY * 0.85:
            if my_status['hp'] > 3 and not is_water_scarce:
                # If HP is good and water is not scarce, can afford to be less aggressive
                calculated_bid = MY_DAILY_SALARY * 0.3
            else:
                # HP low or water scarce, bid aggressively
                calculated_bid = MY_DAILY_SALARY * 0.95
        else: # Moderate pressure
            # Bid slightly above yesterday's highest to secure water
            # Increase increment if water is scarce
            bid_increment = 2.0 if is_water_scarce else 1.5
            calculated_bid = max(MY_DAILY_SALARY * 0.5, highest_prev_bid + bid_increment)

    else: # No yesterday's bids (e.g., Day 1 or all opponents didn't bid/died)
        # On Day 1 or if no prior bids, bid based on HP and scarcity
        if my_status['hp'] <= 2 or is_water_scarce:
            # Desperate or water is scarce, bid aggressively
            calculated_bid = MY_DAILY_SALARY * 0.9
        else:
            # Moderate bid
            calculated_bid = MY_DAILY_SALARY * 0.55

    # Ensure bid does not exceed budget and is non-negative.
    final_bid = min(my_status['budget'], calculated_bid)
    return max(0.0, final_bid)
